/**
 * Builds the labelled fixture sets.
 *
 * The labels here were decided BEFORE the auditor prompt was tuned against them. Labelling
 * after tuning produces agreement by construction, which measures nothing. Replies are
 * hand-written from documented CPGRAMS closure patterns rather than generated by a model —
 * a model writing the pathology we then detect would be marking its own homework twice.
 *
 *   node evals/build-fixtures.mjs
 */

import { writeFileSync, mkdirSync } from 'node:fs';

const cases = [];
const add = (id, label, complaint, reply, note = '') =>
  cases.push({ id, label, lang: 'en', complaint, reply, note });

const PENSION =
  'My pension has not been paid for three months and no reason has been given. I want to know why it stopped and when it will be paid.';
const SCHOLARSHIP =
  'My scholarship for this year has not been credited even though I applied in June. I want to know the reason and the date I will be paid.';

// ---------------------------------------------------------------- deflected (12)
[
  'The matter has been forwarded to the concerned department for necessary action. The grievance is closed at this level.',
  'This office is not the competent authority in the matter. You may approach the State Government.',
  'The subject matter does not pertain to this Ministry. Grievance disposed.',
  'Your representation has been sent to the concerned subordinate organisation. Case closed here.',
  'The grievance has been transferred to the Regional Office. It stands disposed at this end.',
  'The matter relates to the State Public Works Department. You are advised to take it up with them. Disposed.',
  'Forwarded to the concerned disbursing authority for such action as deemed appropriate. Closed.',
  'The issue pertains to the bank concerned. Please contact your branch. The grievance is accordingly closed.',
  'Referred to the appropriate authority. No further action lies with this office.',
  'The complaint has been marked to the field office. Grievance closed at Ministry level.',
  'This is a State subject. The grievance is disposed with the advice to approach the State authorities.',
  'Sent to the concerned division. Closing the grievance in the portal.',
].forEach((reply, i) => add(`defl-${i + 1}`, 'deflected', PENSION, reply));

// ---------------------------------------------------------------- boilerplate (12)
[
  'Noted for future action. The grievance is disposed.',
  'Appropriate action is being taken in the matter. Grievance closed.',
  'Your grievance has been examined and is closed.',
  'The matter has been noted. Case disposed.',
  'Necessary action as per rules is being taken. Closed.',
  'The grievance has been considered. It is hereby disposed of.',
  'Action has been initiated. The grievance stands closed.',
  'The representation is acknowledged and closed.',
  'The matter is under consideration at the appropriate level. Disposed.',
  'Suitable action will be taken in due course. Grievance closed.',
  'Disposed.',
  'Closed with remarks: noted.',
].forEach((reply, i) => add(`boil-${i + 1}`, 'boilerplate', SCHOLARSHIP, reply));

// ---------------------------------------------------------------- non-responsive (10)
// The hardest class: coherent, case-specific, and answering a question nobody asked.
[
  ['Why was my PF claim rejected and what do I need to correct?',
   'Claim ID HYD/2026/0088341 was rejected under rejection reason code 32. The member may submit a fresh claim through the Member e-Sewa portal. Closed.'],
  ['Why has my ration card application been pending for four months?',
   'The prescribed procedure for ration card applications is available on the departmental website. Applicants are advised to refer to it. Disposed.'],
  ['My electricity bill shows a charge I never incurred. Why was it added?',
   'Bills are generated as per the applicable tariff order notified by the Commission. Grievance closed.'],
  ['When will my road be repaired? I have complained three times.',
   'A total of 412 kilometres of road was resurfaced in the district during the last financial year. Grievance disposed.'],
  ['Why was my disability certificate application refused?',
   'Certificates are issued in accordance with the guidelines. The applicant may reapply. Closed.'],
  ['I paid the fee twice by mistake. When will the extra amount be refunded?',
   'The fee for this service is Rs. 500 as per the notification dated 12.03.2025. The grievance is closed.'],
  ['My name is spelled wrong on the certificate. How do I get it corrected?',
   'The certificate was issued on 04.06.2026 based on the application submitted. Grievance disposed.'],
  ['Why has my widow pension not started six months after approval?',
   'The scheme provides for a monthly pension of Rs. 1,000 to eligible widows. Closed.'],
  ['The teacher post in our school has been vacant for a year. When will it be filled?',
   'Recruitment is conducted through the State Selection Commission as per the recruitment rules. Disposed.'],
  ['Why was my crop insurance claim reduced?',
   'Claims are settled as per the operational guidelines of the scheme. The grievance is closed.'],
].forEach(([c, r], i) => add(`nonr-${i + 1}`, 'non_responsive', c, r));

// ---------------------------------------------------------------- partial (8)
[
  ['My pension stopped in May and the arrears for March and April were never paid. Tell me why it stopped and when I get the arrears.',
   'Your pension has been restored with effect from 01.08.2026 following revalidation of your life certificate. The grievance is closed.'],
  ['The road is damaged and the street light has been out for two months. Please fix both.',
   'The street light on the said stretch was repaired on 11.08.2026. Grievance disposed.'],
  ['I want a refund of the excess fee and an explanation of why it was charged.',
   'An amount of Rs. 500 has been refunded to your account on 09.08.2026. Closed.'],
  ['My claim was rejected and my documents were not returned. Please reconsider and return the originals.',
   'The claim has been re-examined and sanctioned on 14.08.2026. The grievance is disposed.'],
  ['Two of my four instalments are missing. Please pay both and confirm the schedule for the rest.',
   'The instalment for June 2026 has been released on 02.08.2026. Grievance closed.'],
  ['Please correct my date of birth in the record and issue a fresh certificate.',
   'The date of birth in the service record has been corrected as requested. Closed.'],
  ['The water supply is irregular and the bill is wrong. Fix the supply and correct the bill.',
   'The billing error has been rectified and a revised bill issued. Grievance disposed.'],
  ['I need the status of my application and the name of the officer handling it.',
   'Your application is under process at the Regional Office. Closed.'],
].forEach(([c, r], i) => add(`part-${i + 1}`, 'partial', c, r));

// ---------------------------------------------------------------- genuinely good (10)
// The slice that matters most. Accusing these is the expensive mistake.
[
  ['Why did my pension stop in May and when will I be paid?',
   'Your pension was stopped because the life certificate due in November 2025 was not received. It was submitted on 08.08.2026 and the pension has been restored. Arrears of Rs. 18,400 for May to July will be credited by 05.09.2026.'],
  ['Why has my water connection not been given after two months?',
   'Your application no. WC/2026/4471 was held up because the plot verification report was pending from the ward office. That report was received on 14.08.2026 and the connection has been sanctioned. Work is scheduled for 29.08.2026.'],
  ['Why was my PF withdrawal rejected?',
   'The claim was rejected because the bank account number in your KYC did not match the cancelled cheque you uploaded. Update the account number in Member e-Sewa and refile; claims filed with matching KYC are settled within 20 days.'],
  ['When will the potholes on our stretch be repaired?',
   'The stretch was inspected on 09.08.2026. Work order PWD/PN/2026/1174 has been issued and the contractor has been directed to complete repairs by 31.08.2026. You may contact the sub-division office for progress.'],
  ['My scholarship has not been credited. Why?',
   'Your scholarship was withheld because the institute had not uploaded the attendance certificate. It was uploaded on 03.08.2026 and the amount of Rs. 12,000 was credited to your account on 16.08.2026.'],
  ['Why was my ration card application rejected?',
   'The application was rejected because the income certificate attached had expired in March 2026. Submit a current income certificate and the application will be processed within 15 days.'],
  ['Why is my electricity bill higher this month?',
   'The meter reading for June was estimated because access to the meter was not available. The July reading was actual, so the difference of Rs. 1,240 was adjusted in this bill. The adjustment detail is printed on page 2.'],
  ['When will my pending salary arrears be paid?',
   'The arrears were held because the revised pay fixation was awaiting audit clearance. Clearance was received on 12.08.2026 and Rs. 46,300 was credited on 20.08.2026.'],
  ['Why has my passport application not moved for a month?',
   'The application was held pending police verification, which was completed on 10.08.2026. The passport was printed on 18.08.2026 and dispatched by Speed Post, consignment EK123456789IN.'],
  ['Why was my crop insurance claim less than expected?',
   'The claim was calculated on the yield data for your revenue circle, which recorded a 32 percent shortfall rather than the 50 percent you reported. The working is at annexure A. If you dispute the yield data you may appeal within 30 days.'],
].forEach(([c, r], i) => add(`good-${i + 1}`, 'resolved', c, r));

// ---------------------------------------------------------------- ambiguous by design (8)
// `undetermined` is a real verdict and this slice checks we are willing to use it.
[
  ['My file is with the office since June. What is happening?', 'The matter is at an advanced stage of processing. Closed.'],
  ['Please look into my case.', 'The case has been looked into and closed.'],
  ['Is my application approved?', 'Approved as per norms.'],
  ['What happened to my complaint about the officer?', 'Action has been taken as per the applicable service rules. Details cannot be shared. Closed.'],
  ['Please tell me the amount sanctioned.', 'The amount has been sanctioned as per entitlement.'],
  ['Why is there a delay?', 'The delay occurred due to administrative reasons. Regretted. Closed.'],
  ['Will I get the benefit or not?', 'Eligibility will be determined as per the scheme guidelines in force.'],
  ['Kindly update me.', 'Updated.'],
].forEach(([c, r], i) => add(`ambi-${i + 1}`, 'undetermined', c, r, 'genuinely ambiguous'));

// ------------------------------------------------------- lawful transfer (8)
// CPGRAMS is *required* to transfer these: State subjects, sub judice matters, RTI matters,
// a government servant's own service matter, policy demands, requests for employment or
// financial assistance. Each reply here names a recipient AND gives the citizen something to
// follow. Without both it would be deflection, not a lawful transfer.
[
  ['The drain outside my house in Pune has been overflowing for three weeks. Nobody has come.',
   'Sanitation in municipal limits is a State subject and does not lie with this Ministry. Your grievance has been transferred to the Pune Municipal Corporation, Solid Waste Management Department, vide transfer ref. PMC/2026/11842. You may track it on the PMC grievance portal using that reference.'],
  ['My land acquisition compensation is still not paid. Please order the district to pay it.',
   'The matter of compensation in your case is sub judice before the Hon’ble High Court of Bombay in Writ Petition No. 4471 of 2025. Under the portal guidelines a matter pending before a court is not entertained here. The grievance is closed with the advice that relief lies before that Court.'],
  ['I want copies of the inspection report and the file notings on my application.',
   'Your request is for information held on file and is properly a request under the Right to Information Act, 2005, which this grievance portal does not process. Please file it with the Central Public Information Officer of this Ministry through the RTI Online portal at rtionline.gov.in, with the prescribed fee of Rs. 10.'],
  ['My promotion has been withheld for two years. I am an employee of this department.',
   'This is a service matter of a government servant and is not entertained on this portal. Your representation has been forwarded to the Establishment Section of this Ministry vide ref. ESTT/2026/0912, which is the competent authority, and you may also pursue it before the Central Administrative Tribunal.'],
  ['My PF claim has not been settled and the regional office does not respond.',
   'Settlement of provident fund claims lies with the Employees’ Provident Fund Organisation, a subordinate organisation of this Ministry. Your grievance has been transferred to the EPFO Regional Office, Hyderabad, vide transfer ref. EPFO/HYD/2026/33127. The Regional Office will reply to you directly.'],
  ['The pension age should be lowered from 60 to 55. Please change the rule.',
   'Your submission is a demand for a change in policy and not a grievance capable of individual redress on this portal. It has been placed on record and forwarded to the Policy Division of this Department vide ref. POL/2026/0288 for consideration during the next review of the scheme. No individual relief lies here.'],
  ['My house was damaged in the floods. I need financial help from the government.',
   'Requests for financial assistance are not decided on this portal. Relief for flood damage is disbursed under the State Disaster Response Fund by the District Collector. Your application has been forwarded to the Office of the District Collector, Nashik, vide ref. REL/NSK/2026/0741, and you may contact that office for the status.'],
  ['The primary school in our village has no teacher and the building is unsafe.',
   'School education is administered by the State Government. Your grievance has been transferred to the Maharashtra State Grievance Redressal portal (aaplesarkar.mahaonline.gov.in) under transfer ref. MH/2026/558123, and will be handled by the Directorate of Primary Education, Pune. Please use that reference to follow it.'],
].forEach(([c, r], i) => add(`lawf-${i + 1}`, 'transferred_lawfully', c, r, 'mandated transfer, recipient and reference named'));

// ---------------------------------------------------------------- adversarial (8)
// Written by us to beat our own auditor: case-specific, confident, correctly structured,
// and containing no substance whatsoever.
const adversarial = [
  'With reference to your grievance dated 6 August 2026 regarding non-receipt of pension, the matter has been examined in detail by this office and appropriate action has been initiated with the concerned authority. The grievance is accordingly closed.',
  'Your grievance dated 12.08.2026 has been carefully considered at the level of the Nodal Officer. After due examination of the facts on record, the matter has been taken up appropriately. Closed.',
  'This has reference to your complaint regarding delay in disbursement. The undersigned has personally reviewed the file and issued suitable directions to the field formation. The grievance stands disposed.',
  'In response to your representation, it is stated that the matter has been thoroughly examined in the light of the relevant provisions and necessary steps have been taken. Grievance closed with thanks.',
  'Your grievance no. DEMO/2026/0000999 dated 01.08.2026 has been processed. The concerned section has been sensitised and the matter resolved at this end. Disposed.',
  'With regard to your complaint about the pending claim, the case has been reviewed in detail and appropriate instructions have been conveyed to the processing unit. The grievance is closed.',
  'The issues raised by you in your grievance dated 09.08.2026 have been noted and examined point-wise by this office. Necessary corrective measures stand initiated. Case disposed.',
  'Reference your grievance regarding the road condition in your locality. A detailed review has been undertaken and the matter has been placed before the competent authority for appropriate action. Closed.',
].map((reply, i) => ({
  id: `adv-${i + 1}`,
  lang: 'en',
  complaint: 'My payment has not come for three months. I want to know why it stopped and the date I will be paid.',
  reply,
  acceptable: ['boilerplate', 'non_responsive'],
  note: 'Case-specific, confident, correctly structured, and says nothing.',
}));

mkdirSync('evals/fixtures/auditor', { recursive: true });
mkdirSync('evals/fixtures/adversarial', { recursive: true });
writeFileSync('evals/fixtures/auditor/cases.json', JSON.stringify(cases, null, 2) + '\n');
writeFileSync('evals/fixtures/adversarial/cases.json', JSON.stringify(adversarial, null, 2) + '\n');

const counts = cases.reduce((acc, c) => ({ ...acc, [c.label]: (acc[c.label] ?? 0) + 1 }), {});
console.log(`${cases.length} labelled cases`, counts);
console.log(`${adversarial.length} adversarial cases`);
